 10	    public static void sort(int[] values) {
 11	        Objects.requireNonNull(values, "values");
 12	        sortRange(values, 0, values.length);
 13	    }
 14	
 15	    public static void sort(int[] values, int fromIndex, int toIndexExclusive) {
 16	        Objects.requireNonNull(values, "values");
 17	        sortRange(values, fromIndex, toIndexExclusive);
 18	    }
 19	
 20	    private static void sortRange(int[] values, int fromIndex, int toIndexExclusive) {
 21	        Objects.checkFromToIndex(fromIndex, toIndexExclusive, values.length);
 22	        if (toIndexExclusive - fromIndex < 2) {
 23	            return;
 24	        }
 25	
 26	        quickSort(values, fromIndex, toIndexExclusive);
 27	    }
 28	
 29	    private static void quickSort(int[] values, int left, int rightExclusive) {
 30	        while (rightExclusive - left > INSERTION_SORT_THRESHOLD) {
 31	            Partition partition = partition(values, left, rightExclusive);
 32	            int leftSize = partition.lessThanEndExclusive() - left;
 33	            int rightSize = rightExclusive - partition.greaterThanStart();
 34	
 35	            if (leftSize < rightSize) {
 36	                quickSort(values, left, partition.lessThanEndExclusive());
 37	                left = partition.greaterThanStart();
 38	            } else {
 39	                quickSort(values, partition.greaterThanStart(), rightExclusive);
 40	                rightExclusive = partition.lessThanEndExclusive();
 41	            }
 42	        }
 43	
 44	        insertionSort(values, left, rightExclusive);
 45	    }
 46	
 47	    private static Partition partition(int[] values, int left, int rightExclusive) {
 48	        int pivot = medianOfThreeValue(values, left, rightExclusive);
 49	        int lessThan = left;
 50	        int index = left;
 51	        int greaterThan = rightExclusive - 1;
 52	
 53	        while (index <= greaterThan) {
 54	            int current = values[index];
 55	            if (current < pivot) {
 56	                swap(values, lessThan, index);
 57	                lessThan++;
 58	                index++;
 59	            } else if (current > pivot) {
 60	                swap(values, index, greaterThan);
 61	                greaterThan--;
 62	            } else {
 63	                index++;
 64	            }
 65	        }
 66	
 67	        return new Partition(lessThan, greaterThan + 1);
 68	    }
 69	
 70	    private static int medianOfThreeValue(int[] values, int left, int rightExclusive) {
 71	        int middle = left + ((rightExclusive - left - 1) >>> 1);
 72	        int right = rightExclusive - 1;
 73	
 74	        int leftValue = values[left];
 75	        int middleValue = values[middle];
 76	        int rightValue = values[right];
 77	
 78	        if (leftValue < middleValue) {
 79	            if (middleValue < rightValue) {
 80	                return middleValue;
 81	            }
 82	            return Math.max(leftValue, rightValue);
 83	        }
 84	
 85	        if (leftValue < rightValue) {
 86	            return leftValue;
 87	        }
 88	
 89	        return Math.max(middleValue, rightValue);
 90	    }
 91	
 92	    private static void insertionSort(int[] values, int left, int rightExclusive) {
 93	        for (int index = left + 1; index < rightExclusive; index++) {
 94	            int currentValue = values[index];
 95	            int position = index - 1;
 96	
 97	            while (position >= left && values[position] > currentValue) {
 98	                values[position + 1] = values[position];
 99	                position--;
100	            }
101	
102	            values[position + 1] = currentValue;
103	        }
104	    }
105	
106	    private static void swap(int[] values, int first, int second) {
107	        int temp = values[first];
108	        values[first] = values[second];
109	        values[second] = temp;
110	    }
111	
