113	        private final int lessThanEndExclusive;
114	        private final int greaterThanStart;
115	
116	        private Partition(int lessThanEndExclusive, int greaterThanStart) {
117	            this.lessThanEndExclusive = lessThanEndExclusive;
118	            this.greaterThanStart = greaterThanStart;
119	        }
