10	        runCase("sort requested range", QuickSortTest::shouldSortOnlyRequestedRange);
11	        runCase("handle duplicates and empty input", QuickSortTest::shouldHandleDuplicatesAndEmptyInputs);
12	        runCase("sort many duplicates", QuickSortTest::shouldSortManyDuplicates);
13	        runCase("reject invalid ranges", QuickSortTest::shouldRejectInvalidRanges);
