16	    private static void shouldSortWholeArray() {
17	        int[] values = {10, 7, 8, 9, 1, 5};
18	        QuickSort.sort(values);
19	        assertArrayEquals(new int[] {1, 5, 7, 8, 9, 10}, values);
20	    }
