22	    private static void shouldSortOnlyRequestedRange() {
23	        int[] values = {9, 4, 3, 8, 1, 7};
24	        QuickSort.sort(values, 1, 5);
25	        assertArrayEquals(new int[] {9, 1, 3, 4, 8, 7}, values);
