44	    private static void shouldRejectInvalidRanges() {
45	        expectThrows(IndexOutOfBoundsException.class, () -> QuickSort.sort(new int[] {1, 2, 3}, -1, 2));
46	        expectThrows(IndexOutOfBoundsException.class, () -> QuickSort.sort(new int[] {1, 2, 3}, 0, 4));
47	        expectThrows(IndexOutOfBoundsException.class, () -> QuickSort.sort(new int[] {1, 2, 3}, 2, 1));
48	    }
