58	    private static void assertArrayEquals(int[] expected, int[] actual) {
59	        if (!Arrays.equals(expected, actual)) {
60	            throw new AssertionError(
61	                    "Expected " + Arrays.toString(expected) + " but found " + Arrays.toString(actual));
62	        }
